OnyxUpdateManager();
describe('actions/ReportField', () => {
    function connectToFetchPolicy(policyID: string): Promise<OnyxEntry<PolicyType>> {
        return new Promise((resolve) => {
            const connection = Onyx.connect({
                key: `${ONYXKEYS.COLLECTION.POLICY}${policyID}`,
